std::set<std::string> WMessageResources::keys(const WLocale& locale) const
{
  load(locale);

  std::set<std::string> keys;

  for (auto& r : resources_) {
    if (r.first == locale.name()) {
      for (auto& k : r.second.map_)
        keys.insert(k.first);
      break;
    }
  }

  return keys;
}

